/* Parent / administration collaboration. Demo data remain browser-local. */
if(!demo.familySpace){demo.familySpace={parents:[{id:'P-DEMO-01',name:'Parent Exemple A',children:demo.students.filter(s=>['DEMO-001','DEMO-003'].includes(s.id)).map(s=>s.id)},{id:'P-DEMO-02',name:'Parent Exemple B',children:demo.students.filter(s=>s.id==='DEMO-002').map(s=>s.id)}],threads:[],bulletins:[]};const c=demo.students.find(s=>s.id==='DEMO-003');if(c&&!c.parent)c.parent='Parent Exemple A';const rows=demo.results.filter(r=>r.student==='DEMO-001'&&r.period==='1er trimestre');if(rows.length)demo.familySpace.bulletins.push({id:'BUL-DEMO-001',student:'DEMO-001',period:'1er trimestre',year:'2026–2027',state:'Publié',rows:rows.map(r=>({...r})),comment:'Exemple de bulletin pour la démonstration.',publishedAt:new Date().toISOString()});demo.familySpace.threads.push({id:'MSG-DEMO-001',parent:'P-DEMO-01',student:'DEMO-001',type:'Convocation',subject:'Rencontre de suivi scolaire',body:'Exemple fictif : nous vous proposons un échange sur la scolarité de votre enfant. Vous pouvez répondre ici pour convenir d’une date.',appointment:'',place:'Bureau de l’administration',sender:'Administration',createdAt:new Date().toISOString(),readAt:null,ackAt:null,attendance:false,replies:[]},{id:'MSG-DEMO-002',parent:'P-DEMO-01',student:'DEMO-001',type:'Punition',subject:'Information sur une mesure éducative',body:'Exemple fictif : une mesure éducative a été signalée par l’administration. Merci de prendre connaissance de ce message et de nous contacter pour en discuter.',appointment:'',place:'',sender:'Administration',createdAt:new Date().toISOString(),readAt:null,ackAt:null,attendance:false,replies:[]});save();}
const familyRecordId=()=>Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,8).toUpperCase();
const fs=demo.familySpace;let activeParentId=fs.parents[0]?.id||'',activeChildId='',activeThreadId='',bulletinPreviewId='';
const familyParent=()=>fs.parents.find(p=>p.id===activeParentId);
const familyChildren=()=>demo.students.filter(s=>familyParent()?.children.includes(s.id));
function ensureFamilyChild(){const children=familyChildren();if(!children.some(c=>c.id===activeChildId)){activeChildId=children[0]?.id||'';activeThreadId='';}return children.find(c=>c.id===activeChildId);}
const familyThreads=()=>fs.threads.filter(t=>t.parent===activeParentId&&t.student===activeChildId);
const publishedBulletins=()=>fs.bulletins.filter(b=>b.student===activeChildId&&b.state==='Publié');
const isParentUnread=t=>t.parentUnread??(!t.readAt&&t.sender==='Administration');
const localDate=v=>v?new Date(v).toLocaleString('fr-FR',{timeZone:'Africa/Lubumbashi',dateStyle:'short',timeStyle:'short'}):'Non renseigné';
const parentNotice=()=>`<p class="parent-demo">Démonstration avec des familles fictives · Les échanges restent dans ce navigateur. Les comptes parent sécurisés et les envois externes ne sont pas encore activés.</p>`;
Object.assign(carnetLabels,{bulletins:'Bulletins',communications:'Communications',familles:'Familles'});
Object.assign(moduleDefs,{bulletins:['Bulletins','Versions publiées par le collège','book','blue'],communications:['Communications','Messages, convocations et mesures éducatives','bell','rose'],familles:['Familles','Responsables et enfants rattachés','people','mint']});
const navBeforeParents=carnetNavItems;carnetNavItems=function(){return role==='Parent'?['dashboard','horaires','bulletins','communications','profil']:role==='Administration'?[...navBeforeParents().slice(0,-1),'bulletins','communications','familles','profil']:navBeforeParents();};
const labelBeforeParents=carnetLabel;carnetLabel=function(k){return role==='Parent'&&k==='horaires'?'Horaire de mon enfant':role==='Parent'&&k==='profil'?'Ma famille':labelBeforeParents(k);};
const parentDashboardBefore=dashboard;
dashboard=function(){if(role==='Parent'){const child=ensureFamilyChild(),threads=familyThreads(),unread=threads.filter(isParentUnread).length;if(!child)return `<h1>Bienvenue dans votre espace parent</h1><p>Aucun enfant n’est rattaché à cette famille. L’administration doit valider le rattachement.</p>${parentNotice()}`;return `<div class="carnet-intro"><div><span class="carnet-kicker">LE LIEN AVEC LE COLLÈGE</span><h1>Bienvenue, ${esc(familyParent().name)}.</h1><p>Le parcours de votre enfant et les échanges avec l’administration.</p></div><span class="carnet-role">Parent</span></div><div class="carnet-overview"><article class="carnet-feature"><span class="carnet-kicker">L’ENFANT SÉLECTIONNÉ</span><h2>${esc(child.name)}</h2><p>${esc(child.section)} · ${esc(child.classe)}<br>Matricule ${esc(child.id)}</p><button class="btn carnet-light" data-tab="bulletins">${ico('book')} Consulter ses bulletins →</button><span class="carnet-values">TRAVAIL · MAÎTRISE · DROITURE</span></article><article class="carnet-account"><span class="carnet-kicker">NOS ÉCHANGES</span><div class="carnet-balance"><span>Messages de l’administration non lus</span><strong>${unread}</strong></div><dl><div><dt>Bulletins publiés</dt><dd>${publishedBulletins().length}</dd></div><div><dt>Enfants rattachés</dt><dd>${familyChildren().length}</dd></div></dl><button class="carnet-text-button" data-tab="communications">Ouvrir les communications →</button></article></div><div class="carnet-section-heading"><div><span class="carnet-kicker">ACCOMPAGNER SA SCOLARITÉ</span><h2>Tout pour suivre votre enfant.</h2></div></div><div class="carnet-actions">${['horaires','bulletins','communications'].map(carnetButton).join('')}</div>${parentNotice()}`;}const output=parentDashboardBefore();return role==='Administration'?output.replace('<div class="carnet-demo-note">',`<div class="carnet-section-heading"><div><span class="carnet-kicker">LE LIEN AVEC LES FAMILLES</span><h2>Informer et dialoguer.</h2></div></div><div class="carnet-actions">${['familles','bulletins','communications'].map(carnetButton).join('')}</div><div class="carnet-demo-note">`):output;};
function bulletinDocument(b){const child=demo.students.find(s=>s.id===b.student);return `<article class="bulletin-paper"><div class="bulletin-header"><img src="./assets/logo.png" alt="Blason du collège"><div><span class="carnet-kicker">COLLÈGE L’HARMATTAN</span><h3>Bulletin scolaire de démonstration</h3><p>Travail · Maîtrise · Droiture</p></div></div><p><b>${esc(child?.name||b.student)}</b> · ${esc(child?.classe||'')}<br>${esc(b.period)} · Année ${esc(b.year)}<br>Référence : ${esc(b.id)} · ${esc(b.state)}</p>${table(['Cours','Note obtenue','Maximum'],b.rows.map(r=>[esc(r.course),esc(r.score),esc(r.max)]))}<p><b>Appréciation :</b> ${esc(b.comment||'Non renseignée')}</p><p class="bulletin-disclaimer">Document fictif et non officiel. Les règles de calcul, coefficients et modèles de bulletin doivent être validés par la direction. Les seules notes présentées sont celles enregistrées pour cette période.</p></article>`;}
function bulletinsPage(){if(role==='Parent'){const bulletins=publishedBulletins();return `<h2>Les bulletins de mon enfant</h2><p>Seules les versions publiées par le collège sont affichées.</p>${bulletins.length?bulletins.map(b=>`<section class="bulletin-item">${bulletinDocument(b)}<button type="button" class="btn" data-print-bulletin="${esc(b.id)}">Imprimer ou enregistrer en PDF</button></section>`).join(''):`<div class="parent-empty">Aucun bulletin publié pour cet enfant.</div>`}`;}return `<h2>Préparer et publier un bulletin</h2><p>La préparation crée un brouillon à partir des notes existantes. Sa publication le rend visible aux responsables rattachés.</p><form id="prepare-bulletin" class="parent-form"><label>Élève<select name="student" required>${demo.students.map(s=>`<option value="${esc(s.id)}">${esc(s.name)} · ${esc(s.classe)}</option>`).join('')}</select></label><label>Période<select name="period" required>${[...new Set(demo.results.map(r=>r.period))].map(p=>`<option>${esc(p)}</option>`).join('')}</select></label><label>Année scolaire<input name="year" required maxlength="20" value="2026–2027"></label><label>Appréciation<textarea name="comment" maxlength="1200" rows="3"></textarea></label><button class="btn">Préparer le brouillon</button><p id="bulletin-error" role="alert"></p></form><h3>Les versions enregistrées</h3>${fs.bulletins.map(b=>`<article class="bulletin-admin-row"><div><b>${esc(demo.students.find(s=>s.id===b.student)?.name||b.student)}</b><p>${esc(b.period)} · ${esc(b.year)} · <span class="status-pill">${esc(b.state)}</span></p></div><div class="parent-inline-actions"><button class="btn secondary" data-preview-bulletin="${esc(b.id)}">Voir la version</button>${b.state==='Brouillon'?`<button class="btn" data-publish-bulletin="${esc(b.id)}">Publier aux parents</button>`:''}</div></article>`).join('')}${bulletinPreviewId?`<div id="bulletin-preview">${fs.bulletins.filter(b=>b.id===bulletinPreviewId).map(bulletinDocument).join('')}</div>`:''}`;}
function threadCard(t){const replies=t.replies.length;return `<button class="parent-thread ${activeThreadId===t.id?'selected':''}" data-open-thread="${esc(t.id)}"><span class="thread-kind">${esc(t.type)}${role==='Parent'&&isParentUnread(t)?' · Non lu':''}</span><strong>${esc(t.subject)}</strong><span>${esc(demo.students.find(s=>s.id===t.student)?.name||t.student)} · ${esc(fs.parents.find(p=>p.id===t.parent)?.name||'')}</span><small>${replies} réponse${replies>1?'s':''} · ${t.sender==='Parent'?'Message du parent':t.ackAt?'Lecture confirmée':t.readAt?'Consulté':'Non consulté'}</small></button>`;}
function threadDetails(t){if(!t)return `<div class="parent-empty">Choisissez un échange pour lire le message et y répondre.</div>`;return `<article class="thread-detail"><span class="thread-kind">${esc(t.type)} · ${esc(t.sender)}</span><h3>${esc(t.subject)}</h3><p class="thread-stamp">${localDate(t.createdAt)} · heure de Lubumbashi</p><p class="message-text">${esc(t.body)}</p>${t.appointment?`<div class="appointment-box"><b>Rendez-vous</b><p>${esc(t.appointment.replace('T',' à '))} · heure de Lubumbashi<br>${esc(t.place)}</p></div>`:''}${t.place&&!t.appointment?`<p>Lieu proposé : ${esc(t.place)} · date à convenir.</p>`:''}<p class="thread-receipt">${t.sender==='Parent'?'Message adressé à l’administration.':t.ackAt?'Prise de connaissance confirmée le '+localDate(t.ackAt):t.readAt?'Message consulté le '+localDate(t.readAt):'Le parent n’a pas encore consulté ce message.'}${t.attendance?' · Présence au rendez-vous confirmée par le parent.':''}</p>${role==='Parent'&&t.sender==='Administration'?`<div class="parent-inline-actions">${!t.ackAt?`<button class="btn secondary" data-ack-thread="${esc(t.id)}">J’ai pris connaissance du message</button>`:''}${t.type==='Convocation'&&t.appointment&&!t.attendance?`<button class="btn" data-attend-thread="${esc(t.id)}">Confirmer ma présence</button>`:''}</div>`:''}<h3>La conversation</h3>${t.replies.length?t.replies.map(r=>`<div class="thread-reply ${r.role==='Parent'?'from-parent':''}"><b>${esc(r.author)}</b><span>${localDate(r.date)}</span><p class="message-text">${esc(r.body)}</p></div>`).join(''):'<p>Aucune réponse pour le moment.</p>'}<form id="reply-thread" class="parent-form"><label for="thread-reply-text">${role==='Parent'?'Répondre à l’administration':'Répondre au parent'}</label><textarea id="thread-reply-text" name="body" rows="4" required maxlength="3000" placeholder="Écrire votre réponse…"></textarea><button class="btn">Enregistrer la réponse de démonstration</button></form></article>`;}
function communicationsPage(){const threads=role==='Parent'?familyThreads():fs.threads;const selected=threads.find(t=>t.id===activeThreadId);return `<h2>${role==='Parent'?'Échanger avec l’administration':'Communications avec les parents'}</h2><p>Informations, convocations et mesures éducatives sont rattachées à un enfant et à un responsable identifié.</p><details class="new-communication" ${threads.length?'':'open'}><summary>${role==='Parent'?'Écrire un nouveau message':'Créer une communication'}</summary><form id="new-communication" class="parent-form">${role==='Administration'?`<label>Famille et enfant<select name="recipient" required><option value="">Choisir un destinataire</option>${fs.parents.flatMap(p=>demo.students.filter(s=>p.children.includes(s.id)).map(s=>`<option value="${esc(p.id+'|'+s.id)}">${esc(p.name)} · ${esc(s.name)}</option>`)).join('')}</select></label><label>Type de communication<select name="type" id="communication-type"><option>Information</option><option>Convocation</option><option>Punition</option></select></label>`:''}<label>Objet<input name="subject" required maxlength="150"></label><label>Message<textarea name="body" required maxlength="3000" rows="4"></textarea></label>${role==='Administration'?`<div id="appointment-fields" hidden><label>Date et heure de convocation à Lubumbashi<input name="appointment" type="datetime-local"></label><label>Lieu du rendez-vous<input name="place" maxlength="150"></label></div>`:''}<button class="btn">${role==='Parent'?'Enregistrer le message de démonstration':'Transmettre dans l’espace parent de démonstration'}</button></form></details><div class="parent-inbox"><div class="parent-thread-list">${threads.length?threads.slice().reverse().map(threadCard).join(''):'<div class="parent-empty">Aucun échange pour cet enfant.</div>'}</div><div>${threadDetails(selected)}</div></div>${parentNotice()}`;}
function familiesPage(){return `<h2>Familles et rattachements</h2><p>Ces liens déterminent les dossiers visibles dans l’aperçu parent. Leur vérification et leur protection côté serveur restent à développer pour une utilisation réelle.</p>${fs.parents.map(p=>`<article class="bulletin-admin-row"><div><b>${esc(p.name)}</b><p>${demo.students.filter(s=>p.children.includes(s.id)).map(s=>esc(s.name)+' · '+esc(s.classe)).join('<br>')||'Aucun enfant rattaché'}</p></div></article>`).join('')}<h3>Rattacher un enfant fictif</h3><form id="link-family" class="parent-form"><label>Responsable<select name="parent" required>${fs.parents.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><label>Enfant<select name="student" required>${demo.students.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></label><label><input type="checkbox" required> Je confirme avoir vérifié ce rattachement fictif.</label><button class="btn">Ajouter le rattachement</button><p id="family-link-status" role="status"></p></form>`;}
const portalBeforeParents=portalContent;
portalContent=function(){if(tab==='bulletins'&&(role==='Parent'||role==='Administration'))return bulletinsPage();if(tab==='communications'&&(role==='Parent'||role==='Administration'))return communicationsPage();if(tab==='familles'&&role==='Administration')return familiesPage();if(role==='Parent'){const child=ensureFamilyChild();if(tab==='dashboard')return dashboard();if(tab==='profil')return `<h2>Ma famille</h2><p>${esc(familyParent()?.name||'')}</p>${familyChildren().map(c=>`<article class="bulletin-admin-row"><div><b>${esc(c.name)}</b><p>${esc(c.section)} · ${esc(c.classe)}<br>Matricule ${esc(c.id)}</p></div></article>`).join('')}${parentNotice()}`;if(!child)return '<h2>Aucun enfant rattaché</h2>';if(tab==='horaires')return `<h2>L’horaire de ${esc(child.name)}</h2><p>${esc(child.classe)} · Cours et enseignants affectés</p>${schedule(child.classe)}`;return '<h2>Rubrique indisponible dans l’espace parent</h2>';}return portalBeforeParents();};
const layoutBeforeParents=pages.espace;
pages.espace=()=>{if(role==='Parent')ensureFamilyChild();let html=layoutBeforeParents();html=html.replace('</select></label><button id="logout"',`<option ${role==='Parent'?'selected':''}>Parent</option></select></label><button id="logout"`);if(role==='Parent'){const child=ensureFamilyChild();const selector=`<div class="parent-family-picker"><label for="parent-demo-family">Famille de démonstration<select id="parent-demo-family">${fs.parents.map(p=>`<option value="${esc(p.id)}" ${p.id===activeParentId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label for="parent-child-picker">Mon enfant<select id="parent-child-picker" ${child?'':'disabled'}>${familyChildren().map(s=>`<option value="${esc(s.id)}" ${s.id===activeChildId?'selected':''}>${esc(s.name)} · ${esc(s.classe)}</option>`).join('')||'<option>Aucun enfant rattaché</option>'}</select></label></div>`;html=html.replace('<div id="workspace"',selector+'<div id="workspace"');html=html.replace('data-tab="paiements"','data-tab="communications"').replace('<span>Paiements</span>','<span>Messages</span>');}return html;};
const bindBeforeParents=bindPortal;
bindPortal=function(){bindBeforeParents();const on=(id,fn)=>{const f=document.getElementById(id);if(f)f.onsubmit=e=>{e.preventDefault();fn(f,Object.fromEntries(new FormData(f)));};};const viewMode=document.getElementById('carnet-role-select');if(viewMode)viewMode.onchange=()=>{role=viewMode.value;if(role==='Élève')student=demo.students[0];if(role==='Parent')ensureFamilyChild();tab='dashboard';activeThreadId='';render();window.scrollTo(0,0);};const familySelect=document.getElementById('parent-demo-family');if(familySelect)familySelect.onchange=()=>{activeParentId=familySelect.value;activeChildId='';activeThreadId='';render();};const childSelect=document.getElementById('parent-child-picker');if(childSelect)childSelect.onchange=()=>{if(familyChildren().some(s=>s.id===childSelect.value)){activeChildId=childSelect.value;activeThreadId='';render();}};const type=document.getElementById('communication-type');if(type)type.onchange=()=>{const show=type.value==='Convocation';document.getElementById('appointment-fields').hidden=!show;document.querySelector('[name="appointment"]').required=show;document.querySelector('[name="place"]').required=show;};on('prepare-bulletin',(f,d)=>{if(role!=='Administration')return;const rows=demo.results.filter(r=>r.student===d.student&&r.period===d.period);if(!rows.length){document.getElementById('bulletin-error').textContent='Aucune note pour cet élève et cette période. Saisissez les résultats avant de préparer le bulletin.';return;}const id='BUL-'+familyRecordId();fs.bulletins.push({id,student:d.student,period:d.period,year:d.year,state:'Brouillon',rows:rows.map(r=>({...r})),comment:d.comment,publishedAt:null});bulletinPreviewId=id;save();render();});document.querySelectorAll('[data-preview-bulletin]').forEach(b=>b.onclick=()=>{if(role!=='Administration')return;bulletinPreviewId=b.dataset.previewBulletin;render();document.getElementById('bulletin-preview')?.scrollIntoView({behavior:'smooth'});});document.querySelectorAll('[data-publish-bulletin]').forEach(b=>b.onclick=()=>{if(role!=='Administration')return;const item=fs.bulletins.find(x=>x.id===b.dataset.publishBulletin);if(item&&item.state==='Brouillon'){item.state='Publié';item.publishedAt=new Date().toISOString();save();render();}});document.querySelectorAll('[data-print-bulletin]').forEach(b=>b.onclick=()=>{const item=publishedBulletins().find(x=>x.id===b.dataset.printBulletin);if(role!=='Parent'||!item)return;document.querySelectorAll('.bulletin-item').forEach(n=>n.classList.remove('print-bulletin'));b.closest('.bulletin-item').classList.add('print-bulletin');document.body.classList.add('printing-bulletin');window.print();});document.querySelectorAll('[data-open-thread]').forEach(b=>b.onclick=()=>{const t=fs.threads.find(x=>x.id===b.dataset.openThread);if(!t||role==='Parent'&&!familyThreads().some(x=>x.id===t.id)||!['Parent','Administration'].includes(role))return;activeThreadId=t.id;if(role==='Parent'){if(t.sender==='Administration'&&!t.readAt)t.readAt=new Date().toISOString();t.parentUnread=false;save();}render();});document.querySelectorAll('[data-ack-thread]').forEach(b=>b.onclick=()=>{const t=familyThreads().find(x=>x.id===b.dataset.ackThread);if(role!=='Parent'||!t)return;t.ackAt=new Date().toISOString();save();render();});document.querySelectorAll('[data-attend-thread]').forEach(b=>b.onclick=()=>{const t=familyThreads().find(x=>x.id===b.dataset.attendThread);if(role!=='Parent'||!t||!t.appointment)return;t.attendance=true;t.ackAt=new Date().toISOString();save();render();});on('reply-thread',(f,d)=>{const t=fs.threads.find(x=>x.id===activeThreadId);if(!t||!d.body.trim()||role==='Parent'&&!familyThreads().some(x=>x.id===t.id)||!['Parent','Administration'].includes(role))return;if(role==='Administration')t.parentUnread=true;t.replies.push({role,author:role==='Parent'?familyParent().name:'Administration',body:d.body.trim(),date:new Date().toISOString()});save();render();});on('new-communication',(f,d)=>{if(!['Parent','Administration'].includes(role))return;const [pid,sid]=role==='Administration'?(d.recipient||'').split('|'):[activeParentId,activeChildId];if(!fs.parents.some(p=>p.id===pid&&p.children.includes(sid))||!d.body.trim()||!d.subject.trim())return;const t={id:'MSG-'+familyRecordId(),parent:pid,student:sid,type:role==='Parent'?'Message du parent':d.type,subject:d.subject.trim(),body:d.body.trim(),appointment:role==='Administration'&&d.type==='Convocation'?d.appointment:'',place:role==='Administration'&&d.type==='Convocation'?d.place:'',sender:role,createdAt:new Date().toISOString(),readAt:null,ackAt:null,attendance:false,replies:[]};fs.threads.push(t);activeThreadId=t.id;save();render();});on('link-family',(f,d)=>{if(role!=='Administration')return;const p=fs.parents.find(x=>x.id===d.parent);if(p&&!p.children.includes(d.student)){p.children.push(d.student);save();render();}else document.getElementById('family-link-status').textContent='Cet enfant est déjà rattaché à ce responsable.';});};
window.addEventListener('afterprint',()=>{document.body.classList.remove('printing-bulletin');document.querySelectorAll('.print-bulletin').forEach(n=>n.classList.remove('print-bulletin'));});
render();
document.addEventListener('click',e=>{if(!e.target.closest('[data-open-parent]'))return;e.preventDefault();role='Parent';tab='dashboard';activeThreadId='';ensureFamilyChild();if(location.hash==='#espace'){render();window.scrollTo(0,0);}else location.hash='espace';});
